#!/usr/bin/env python3
from pathlib import Path
import json,hashlib
from draw_enemy_events import SPECS
R=Path(__file__).resolve().parents[1]
contracts={
'death':{'event':'EnemyDied','guard':'confirmed death only; prefer split/transform for a paired EnemySplit; not flee','target':'defeated enemy instance at its pre-removal feet','sprite_sync':{'top_down_hide_fraction':[0,.15,.32,.50,.70,.87,1,1],'terminal':'old sprite remains hidden'}},
'steal':{'event':'GoldStolen','guard':'amount > 0; emitted on declaration, not steal-gold action resolution','target':'stealing enemy; local bag feedback, not a second gold transfer','sprite_sync':None},
'flee':{'event':'EnemyFled','guard':'confirmed flee, not intent or cancelled action','target':'pre-removal feet; dust is stationary','sprite_sync':{'rightward_offset_px':[0,2,7,14,23,34,44,64],'terminal':'old sprite hidden; do not restore on cancellation','mirror_rule':'leftward exit mirrors texture and x offsets together'}},
'split':{'event':'EnemySplit','guard':'count > 1 and confirmed spawned instances; do not invent children from count alone','target':'original instance pre-removal feet','sprite_sync':{'old_visible_frames':[0,1,2],'reveal_children_at_frame':3,'children':'actual spawned instances at their authoritative positions; never duplicate original art'}},
'hatch':{'event':'EnemyHatched','guard':'confirmed old-to-new form, not hatch intent or blocked hatch','target':'hatching instance feet','sprite_sync':{'old_visible_frames':[0,1],'new_visible_from_frame':2,'terminal':'new form stays visible; no crossfade duplicate body'}},
 'transform':{'event':'EnemySplit','guard':'count == 1 and confirmed successor from remaining-life chain; not arbitrary summon','target':'original feet; successor uses its authoritative position','sprite_sync':{'old_visible_frames':[0,1,2],'both_hidden_frames':[3],'new_visible_from_frame':4,'terminal':'successor stays; old instance stays hidden'}},
'rally':{'event':'StrengthGained in confirmed rally resolution group','guard':'resolve action kind rally and amount > 0; generic StrengthGained alone is insufficient','target':'one drum/ring at source, not one drum for every buff recipient','sprite_sync':{'recipients':'only actual resolved living recipients; optional local brass tint at frame 2','count_rule':'deduplicate by source action receipt; no double playback for per-recipient events'}},
'heal':{'event':'EnemyHealed','guard':'amount > 0; presentationReceipt timing wins','target':'targetIndex (healed recipient), not enemyIndex (caster)','sprite_sync':None},
'mill':{'event':'CardsMilled associated with confirmed enemy mill action','guard':'count > 0 and source is resolved enemy kind mill; player milling must not trigger enemy eating','target':'confirmed eating enemy; local emblem only','sprite_sync':{'card_rule':'one generic blue card symbol per event, not one per actual card; counts and IDs stay in UI','no_fallback_target':True}},
'enrage':{'event':'StrengthGained','guard':'amount > 0 and reason one of enrage-cards, enrage-damage, enrage-phase','target':'enemyIndex','sprite_sync':{'exclude':'mourn, rally, generic buff and strength gained from eaten cards','repeat_rule':'one per resolved event; coalesce within one presentation group if needed'}}}
assets=[]
for name,label,times in SPECS:
 file=f'Art/fx/enemy_{name}_8f.png'
 assets.append({'id':'enemy_'+name,'label_ja':label,'file':file,'size':[512,64],'frame_size':[64,64],'frame_count':8,'layout':'horizontal','anchor_px_top_left':[32,52],'anchor_normalized_top_left':[.5,.8125],'right_facing':True,'duration_ms':times,'total_duration_ms':sum(times),'frames':[{'index':i,'rect':[64*i,0,64,64],'duration_ms':t} for i,t in enumerate(times)],'final_frame_fully_transparent':True,'loop':False,'layer':'effect above actor artwork, below numbers/labels/tooltips','trigger_contract':contracts[name],'sha256':hashlib.sha256((R/file).read_bytes()).hexdigest()})
m={'schema':'deckrogue.asset-handoff.v1','bundle':'B7 enemy events','date':'2026-11-08','branch':'codex/assets-b7-20261108','status':'asset-only; no runtime integration verified','source_reference_commit':'114ee430310c5a2df02ea048f23d1f8375c22c66','generation':'original direct integer-pixel drawing, no source game sprites or generated high-resolution image','theme':'night glass and fine brass, B1-B6 palette','format':{'mode':'RGBA','bit_depth':8,'alpha_values':[0,255],'filter':'nearest','mipmaps':False,'compression':'lossless','blend':'normal straight alpha','trim':False,'atlas_rotation':False,'pixel_scale':'same logical pixel grid; integer scaling only; do not shrink to fit actor bounding box'},'global_contract':{'coordinates':'PNG pixels; origin top-left; y down','authoritative_logic':'never derive damage, counts, state, spawn or rewards from image or animation frames','timing':'recommendations only; resolved presentation timing is authoritative','interrupt':'remove temporary VFX; reset temporary tints and offsets; preserve confirmed death/flee/transformed state','reduced_motion':'skip actor translation or masking, display brief local key frame; never delay gameplay','deduplication':'one applicable transition effect for a death/split/transform chain, not three','runtime_changes_included':False},'assets':assets}
(R/'manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':print('manifest: 10 assets')
